871	/**
872	 * A gate's `error.message` split on `"; "` into reasons keyed by their `<check id>: ` prefix. A segment without one is a
873	 * gate-level reason; it is also attached to a check only when the text after `<path>` is the tail of exactly one check's
874	 * command (the message is redacted, the command is not). With two or more matching tails, or none, it stays gate-level.
875	 */
876	export function gateReasonsByCheck(message: string | null | undefined, checks: readonly { id: string; command: string }[]): GateReasons {
877	  const ids = [...checks].sort((a, b) => b.id.length - a.id.length)
878	  const reasons = (message ?? '').split('; ').map(segment => segment.trim()).filter(Boolean).map((text): GateReason => {
879	    const keyed = ids.find(check => text.startsWith(`${check.id}: `))
880	    if (keyed) return { text, reason: text.slice(keyed.id.length + 2), check_id: keyed.id, attached_to: null }
881	    const at = text.lastIndexOf('<path>')
882	    const tail = at < 0 ? '' : text.slice(at + '<path>'.length)
883	    const matching = tail.trim() ? checks.filter(check => check.command.endsWith(tail)) : []
884	    return { text, reason: text, check_id: null, attached_to: matching.length === 1 ? matching[0].id : null }
885	  })
886	  const byCheck = new Map<string, GateReason[]>()
887	  for (const reason of reasons) {
888	    const id = reason.check_id ?? reason.attached_to
889	    if (id !== null) byCheck.set(id, [...byCheck.get(id) ?? [], reason])
890	  }
891	  return { reasons, gate: reasons.filter(reason => reason.check_id === null), byCheck }
892	}
